insert into public.catalog_collections (brand_id,name,category,description,is_active,sort_order) select id,'Solara','interior','Міжкімнатні двері StilDoors колекції Solara.',true,73 from public.catalog_brands where name='StilDoors' on conflict (brand_id,name,category) do update set description=excluded.description,is_active=true,updated_at=now();
